package org.codex.nfsugpreview;
import java.nio.*;import java.nio.file.*;import java.util.*;
public final class RoadBatchingTest {
 public static void main(String[] args)throws Exception{Path dir=Paths.get(args[0]);int scenes=0,before=0,after=0,cells=0;try(DirectoryStream<Path> files=Files.newDirectoryStream(dir,"source-race-background-*.nrb")){for(Path path:files){NativeSceneSnapshot scene=new NativeBackgroundScene(Files.readAllBytes(path)).sky.scene;NativeRoadHistory[] histories=new NativeRoadHistory[scene.geometryCount()];byte[][] proofs=new byte[histories.length][];for(int owner=0;owner<histories.length;owner++){long serial=scene.geometry(owner).serial;histories[owner]=new NativeRoadHistory(Files.readAllBytes(dir.resolve("owner-"+serial+".nrh")));proofs[owner]=Files.readAllBytes(dir.resolve("owner-"+serial+".nrp"));NativeRoadHistory.Samples samples=histories[owner].samples(scene.epoch,scene.geometry(owner).endRefresh,scene.geometry(owner).page);Set<Integer> originalEvents=new HashSet<>();int top=owner==0?0:scene.splitRow,bottom=histories.length==1||owner==1?160:scene.splitRow;for(int cell=top*240;cell<bottom*240;cell++)if(proofs[owner][80+cell]==1)originalEvents.add(samples.event(cell));before+=originalEvents.size();}NativeRoadRetention retained=new NativeRoadRetention(scene,histories,proofs);boolean[] seen=new boolean[38400];for(int d=0;d<retained.count();d++){NativeRoadRetention.Draw draw=retained.draw(d);int[] records=draw.records();ByteBuffer texture=retained.texture(draw);NativeRoadHistory.Samples original=histories[draw.owner].samples(scene.epoch,scene.geometry(draw.owner).endRefresh,scene.geometry(draw.owner).page);for(int at=0;at<records.length;at+=3){int cell=records[at+1]*240+records[at];if(seen[cell])throw new AssertionError("Batch cell overlap");seen[cell]=true;NativeRoadHistory.Event event=histories[draw.owner].event(original.event(cell));if(texture.get(records[at+2])!=event.texture().get(original.offset(cell))||histories[draw.owner].event(draw.event).assetKey!=event.assetKey)throw new AssertionError("Wrong grouped asset");cells++;}}after+=retained.count();scenes++;}}if(scenes!=9||cells!=100870||after>=before)throw new AssertionError();System.out.println("PASS_ROAD_ASSET_BATCHING scenes="+scenes+" source_cells="+cells+" original_event_batches="+before+" asset_batches="+after+" overlap=0");}
}
